    include_by_default: true
`
	if err := os.WriteFile(filepath.Join(fixture.workDir, ".fizeau", "config.yaml"), []byte(config), 0o600); err != nil {
		t.Fatal(err)
	}
	writeDiscoveryCache(t, fixture.cacheRoot, "alpha", []string{
