func TestSemVer_Less(t *testing.T) {
	tests := []struct {
		name   string
		v      SemVer
		other  SemVer
		want   bool
		reason string
	}{
		{
			name:   "patch less",
			v:      SemVer{Major: 0, Minor: 0, Patch: 7},
			other:  SemVer{Major: 0, Minor: 0, Patch: 8},
			want:   true,
			reason: "v0.0.7 < v0.0.8",
		},
		{
			name:   "patch equal",
			v:      SemVer{Major: 0, Minor: 0, Patch: 8},
